def is_ip_in_subnet(ip_address: str, subnet_mask: str) -> bool:
    def parse(addr):
        parts = addr.split('.')
        if len(parts) != 4:
            return None
        value = 0
        for p in parts:
            if not p or not all(c in '0123456789' for c in p) or int(p) > 255:
                return None
            value = value * 256 + int(p)
        return value
    if subnet_mask.count('/') != 1:
        return False
    net_part, prefix = subnet_mask.split('/')
