canonical_solution:
long long jump(const long long *nums, int nums_len) {
    long long jumps = 0;
    long long reach = 0;
    long long end = 0;
    for (int i = 0; i < nums_len - 1; i++) {
        long long here = (long long)i + nums[i];
        if (here > reach) {
            reach = here;
