function find_substring_concatenations(s, strs) {
  if (!s || strs.length === 0) {
    return [];
  }
  const w = strs[0].length;
  const total = w * strs.length;
  const need = new Map();
  for (const x of strs) {
    need.set(x, (need.get(x) || 0) + 1);
