  const result = [];
  for (let i = 0; i <= s.length - total; i++) {
    const seen = new Map();
    let good = true;
    for (let j = 0; j < strs.length; j++) {
      const piece = s.substring(i + j * w, i + (j + 1) * w);
      const count = (seen.get(piece) || 0) + 1;
      seen.set(piece, count);
