def smallest_subarrays(nums: list[int]) -> list[int]:
    n = len(nums)
    ans = [1] * n
    last = [-1] * 32
    for i in range(n - 1, -1, -1):
        length = 1
        for b in range(32):
            if (nums[i] >> b) & 1:
                last[b] = i
            elif last[b] != -1:
                length = max(length, last[b] - i + 1)
        ans[i] = length
    return ans

