canonical_solution:
function add_to_array_form(num, k) {
  const result = [];
  let i = num.length - 1;
  let carry = k;
  while (i >= 0 || carry > 0) {
    if (i >= 0) {
      carry += num[i];
      i--;
    }
    result.push(carry % 10);
    carry = Math.floor(carry / 10);
  }
  result.reverse();
  return result;
