def find_shortest_substring(text: str, pattern: str) -> str:
    need = set(pattern)
    counts = {}
    have = 0
    left = 0
    best = ""
    for right, ch in enumerate(text):
        if ch in need:
            counts[ch] = counts.get(ch, 0) + 1
            if counts[ch] == 1:
                have += 1
        while have == len(need):
            if best == "" or right - left + 1 < len(best):
                best = text[left:right + 1]
            lc = text[left]
            if lc in need:
                counts[lc] -= 1
                if counts[lc] == 0:
                    have -= 1
            left += 1
    return best

